SELECT School AS school_name, MailZip AS mailing_zip_code
FROM schools
WHERE AdmFName1 = 'Avetik' AND AdmLName1 = 'Atoian';

SELECT Phone
FROM schools
WHERE Charter = 1 AND FundingType = 'Direct' AND OpenDate > '2000-01-01';

SELECT AVG(`Enrollment (K-12)` - `Enrollment (Ages 5-17)`) AS avg_enrollment_difference
FROM frpm
WHERE `Charter Funding Type` = 'Locally Funded';

SELECT c.printings
FROM cards AS c
WHERE c.artist = 'Daren Bader';

SELECT DISTINCT types
FROM cards
WHERE name = 'Molimo, Maro-Sorcerer';

SELECT COUNT(*) AS high_power_card_count
FROM cards
WHERE artist = 'Aaron Miller' AND power IS NOT NULL AND CAST(power AS INTEGER) > 5;

SELECT COALESCE(SUM(ds.wins), 0) AS victories
FROM driverStandings AS ds
WHERE ds.position = 91;

SELECT COUNT(*) AS president_count
FROM member
WHERE position = 'president';
